  export function CamelPiece({
    color,
    className = "",
    style,
    animateLegs = false,
  }: CamelPieceProps) {
    const generatedId = useId().replaceAll(":", "");
    const rearLegClipId = `camel-rear-leg-${generatedId}`;
    const frontLegClipId = `camel-front-leg-${generatedId}`;
    const bodyMaskId = `camel-body-mask-${generatedId}`;
  
    return (
      <svg
        className={`${className}${
          animateLegs ? " camel-piece--leg-motion" : ""
        }`}
        style={{
          ...style,
          color: CAMEL_COLORS[color],
        }}
        viewBox="0 0 848 625"
        preserveAspectRatio="xMidYMid meet"
        role="img"
        aria-label={`${CAMEL_NAMES[color]} camel`}
        xmlns="http://www.w3.org/2000/svg"
      >
        {animateLegs ? (
          <>
            <defs>
              {/*
                Each animated leg copy extends well into the body.
                The body is drawn last and hides that overlap, which
                prevents the background from opening up at the joints.
              */}
              <clipPath
                id={rearLegClipId}
                clipPathUnits="userSpaceOnUse"
              >
                <rect
                  x="88"
                  y="360"
                  width="310"
                  height="265"
                />
              </clipPath>
  
              <clipPath
                id={frontLegClipId}
                clipPathUnits="userSpaceOnUse"
              >
                <rect
                  x="400"
                  y="360"
                  width="320"
                  height="265"
                />
              </clipPath>
  
              {/*
                Only the lower portions are removed from the body layer.
                The remaining upper-leg area forms a same-color cover over
                the moving layers, so no white seam can appear.
              */}
              <mask
                id={bodyMaskId}
                maskUnits="userSpaceOnUse"
                x="0"
                y="0"
                width="848"
                height="625"
              >
                <rect
                  x="0"
                  y="0"
                  width="848"
                  height="625"
                  fill="white"
                />
  
                <rect
                  x="100"
                  y="505"
                  width="285"
                  height="120"
                  fill="black"
                />
  
                <rect
                  x="425"
                  y="505"
                  width="275"
                  height="120"
                  fill="black"
                />
              </mask>
            </defs>
  
            {/* Animated layers go behind the body overlap. */}
            <g className="camel-piece__leg camel-piece__leg--rear">
              <path
                d={CAMEL_PATH}
                fill="currentColor"
                clipPath={`url(#${rearLegClipId})`}
              />
            </g>
  
            <g className="camel-piece__leg camel-piece__leg--front">
              <path
                d={CAMEL_PATH}
                fill="currentColor"
                clipPath={`url(#${frontLegClipId})`}
              />
            </g>
  
            {/*
              The approved path is unchanged. This top layer masks the
              leg roots and receives only a subtle squash/stretch motion.
            */}
            <g className="camel-piece__body">
              <path
                d={CAMEL_PATH}
                fill="currentColor"
                mask={`url(#${bodyMaskId})`}
              />
            </g>
          </>
        ) : (
          <path
            d={CAMEL_PATH}
            fill="currentColor"
          />
        )}
      </svg>
    );
  }